custom_css:
/* ===== chat.css ===== */
/* =====================================================================
   三联生活周刊 · 一级界面（tokens / 顶栏 / 聊天 / 消息 / 推理 / 输入区）
   真实 DOM 依据：public/index.html #message_template；style.css:753 #top-bar，
   :858 #chat，:877-1000 #form_sheld/#send_form，:1508 .mes_block，:1574 #send_textarea，
   :372-424 .mes_reasoning；toggle-dependent.css:321-366（documentstyle 会隐藏
   name_text，因此本主题用 chat_display 0 平铺模式，自己控制布局）
   ===================================================================== */

/* ---------- tokens（lifeweek.com.cn 官方 CSS 查实） ---------- */
body {
    --song: "宋体-简", "Songti SC", "SimSun", "Noto Serif SC", serif;
    --hei: "黑体-简", "Heiti SC", "PingFang SC", "SimHei", "Noto Sans SC", sans-serif;
    --kai: "楷体-简", "Kaiti SC", "STKaiti", "KaiTi", serif;
    --fang: "华文仿宋", "STFangsong", "FangSong", serif;
    --din: "D-DIN", "DIN Alternate", "DIN Condensed", "Helvetica Neue", sans-serif;
    --red: #cd3737;
    --ink: #222322;
    --g1: #606266;
    --g2: #909190;
    --rule: #dcdfe6;
    --rule2: #e4e7ed;
    --band: #f5f5f3;
    --paper: #ffffff;
    --user-mes-bg: transparent;
    --mainFontFamily: var(--song);
    --monoFontFamily: "SF Mono", Menlo, Consolas, "Noto Sans Mono", monospace;
    font-family: var(--song);
    color: var(--ink);
}

/* 纸面：屏蔽背景图，整页白纸（想保留自己的背景就删掉这一段） */
#bg1,
#bg_custom {
    background-image: none !important;
    background-color: var(--paper) !important;
}

/* ---------- 顶栏 = 周刊页眉 ---------- */
#top-bar {
    background-color: var(--paper) !important;
    border-bottom: 1px solid var(--rule) !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}

/* 刊名行：放在聊天列顶部（顶栏只留图标，宽度不够放刊名） */
#sheld::before {
    content: "三联生活周刊";
    display: block;
    flex: none;
    order: -1;
    padding: 6px 5% 4px 5%;
    background: var(--paper);
    border-bottom: 2px solid var(--ink);
    font-family: var(--hei);
    font-weight: 900;
    font-size: 1.15em;
    letter-spacing: 0.14em;
    color: var(--ink);
    text-align: center;
}

/* ---------- 聊天区 = 正文页 ---------- */
#sheld {
    background: transparent;
}

#chat {
    background-color: var(--paper) !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    text-shadow: none !important;
    padding: 14px 5% 0 5%;
    line-height: 1.85;
}

#chat::before {
    content: "封面故事";
    align-self: flex-start;
    font-family: var(--hei);
    font-size: 0.78em;
    letter-spacing: 0.12em;
    color: #ffffff;
    background: var(--red);
    padding: 1px 9px;
    margin: 0 0 8px 0;
}

/* ---------- 消息 = 访谈体段落 ----------
   name_text 作为黑体前缀与首段同行；推理块整块浮到段前；
   头像默认隐藏（hideChatAvatars），打开头像时退回 flex 布局 */
.mes {
    display: block;
    background: transparent !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    padding: 6px 0;
    margin: 0;
    position: relative;
}

body:not(.hideChatAvatars) .mes {
    display: flex;
}

.mes_block {
    padding: 0 !important;
    margin: 0 !important;
    overflow: visible !important;
}

.mes .ch_name {
    display: inline !important;
    min-height: 0 !important;
    font-weight: normal;
}

.mes .ch_name .flex-container {
    display: inline !important;
}

.mes .ch_name .name_text {
    display: inline;
    font-family: var(--hei);
    font-weight: 700;
    font-size: 1em;
    color: var(--ink);
}

.mes .ch_name .name_text::after {
    content: "：";
}

/* 用户 = 记者提问：署名原样显示（黑体前缀），整段黑体加粗；主题不改任何人设名 */
.mes[is_user="true"] .mes_text {
    font-family: var(--hei);
    font-weight: 700;
}

.mes[is_user="true"] {
    background: var(--user-mes-bg) !important;
    margin: 4px 0;
}

/* 消息按钮：钉在段落右上角（外观由 popups.css 负责） */
.mes .ch_name .mes_buttons {
    position: absolute;
    right: 0;
    top: 6px;
}

/* 正文 */
.mes_text {
    display: inline;
    padding: 0 !important;
    font-family: var(--song);
    font-weight: 400 !important;
    font-size: 1em;
    line-height: 1.85 !important;
    color: var(--ink);
    text-align: justify;
}

.mes_text > p:first-child {
    display: inline;
}

.mes_text p {
    margin: 0 0 0.6em 0 !important;
}

.mes_text p:last-child {
    margin-bottom: 0.2em !important;
}

.mes_text em,
.mes_text i {
    color: var(--red);
    font-style: normal;
}

.mes_text q {
    color: var(--ink);
}

.mes_text u {
    text-decoration-color: var(--red);
}

.mes_text a {
    color: var(--ink);
    text-decoration: underline;
    text-decoration-color: var(--red);
    text-underline-offset: 3px;
}

.mes_text a:hover {
    color: var(--red);
}

.mes_text h1,
.mes_text h2,
.mes_text h3,
.mes_text h4 {
    font-family: var(--hei);
    font-weight: 700;
    color: var(--ink);
    line-height: 1.3;
    margin: 0.9em 0 0.35em 0;
}

.mes_text h1 {
    font-size: 1.6em;
    letter-spacing: 0.02em;
}

.mes_text h2 {
    font-size: 1.35em;
}

.mes_text h3 {
    font-size: 1.15em;
    padding-left: 10px;
    border-left: 4px solid var(--red);
}

.mes_text h4 {
    font-size: 1em;
    color: var(--g1);
}

/* 放大引语 */
.mes_text blockquote {
    font-family: var(--kai);
    font-size: 1.15em;
    line-height: 1.6;
    color: var(--ink);
    margin: 0.7em 0;
    padding: 0.5em 0;
    border-top: 2px solid var(--red);
    border-bottom: 1px solid var(--rule);
    border-left: 0;
    background: transparent;
}

.mes_text blockquote p {
    margin: 0 !important;
}

/* 表格：表头下粗线，行间细线，无竖线，数字列 DIN */
.mes_text table {
    width: 100%;
    border-collapse: collapse;
    margin: 0.6em 0 0.8em 0;
    font-family: var(--hei);
    font-size: 0.88em;
    line-height: 1.5;
}

.mes_text th,
.mes_text td {
    border: 0 !important;
    border-bottom: 1px solid var(--rule) !important;
    padding: 4px 8px !important;
    text-align: left;
}

.mes_text thead th {
    border-bottom: 2px solid var(--ink) !important;
    color: var(--g1);
    font-weight: 400;
}

.mes_text td:has(> :is(strong, b)):only-of-type,
.mes_text td[align="right"],
.mes_text th[align="right"] {
    font-family: var(--din);
    text-align: right;
}

/* 图片：整宽，下方墨线；图注用紧随其后的斜体段落 */
.mes_text img {
    display: block;
    max-width: 100%;
    margin: 0.6em 0 0.3em 0;
    border-bottom: 2px solid var(--ink);
}

.mes_text img + em,
.mes_text p:has(> img) + p:has(> em:only-child) em {
    display: block;
    font-family: var(--fang);
    font-size: 0.85em;
    color: var(--g1);
    border-left: 2px solid var(--ink);
    padding-left: 6px;
    margin-bottom: 0.6em;
}

.mes_img_container {
    margin: 0.6em 0;
}

.mes_img_container .mes_img_caption {
    font-family: var(--fang);
    font-size: 0.85em;
    color: var(--g1);
    border-left: 2px solid var(--ink);
    padding-left: 6px;
}

/* 代码：浅灰稿纸，左墨线 */
.mes_text pre {
    background: var(--band) !important;
    border: 0;
    border-left: 3px solid var(--ink);
    border-radius: 0;
    padding: 8px 12px;
    margin: 0.5em 0 0.8em 0;
    font-family: var(--monoFontFamily);
    font-size: 0.85em;
    line-height: 1.55;
    color: var(--ink);
}

.mes_text code {
    font-family: var(--monoFontFamily);
    background: var(--band);
    border-radius: 0;
    padding: 0.05em 0.35em;
    color: var(--ink);
}

.mes_text pre code {
    background: transparent;
    padding: 0;
}

/* 列表 */
.mes_text ul,
.mes_text ol {
    margin: 0.3em 0 0.6em 0;
    padding-left: 1.6em;
}

.mes_text li {
    margin: 0.15em 0;
}

.mes_text ol {
    font-variant-numeric: tabular-nums;
}

.mes_text hr {
    border: 0;
    border-top: 1px solid var(--rule);
    margin: 0.8em 0;
}

/* ---------- 推理 = 记者手记：整块浮到段前 ---------- */
.mes_reasoning_details {
    float: right;
    width: 38%;
    max-width: 320px;
    margin: 0.25em 0 0.6em 16px !important;
    background: var(--band);
    border-top: 1px solid var(--ink);
    padding: 6px 12px 8px 12px;
    box-sizing: border-box;
}

.mes_reasoning_details:not([open]) {
    width: auto;
    max-width: none;
    padding: 2px 10px 3px 10px;
}

.mes[is_user="true"] .mes_reasoning_details {
    float: none;
    width: 100%;
    max-width: none;
    margin: 0.3em 0 !important;
}

.mes_reasoning_summary,
.mes_reasoning_header_block,
.mes_reasoning_header {
    background: transparent !important;
    border: 0 !important;
    border-radius: 0 !important;
    padding: 0 !important;
    margin: 0 !important;
    box-shadow: none !important;
    color: var(--ink);
    align-items: center;
}

.mes_reasoning_header_title {
    font-size: 0;
}

.mes_reasoning_header_title::before {
    content: "记者手记";
    font-size: 0.8rem;
    font-family: var(--hei);
    font-weight: 700;
    color: var(--ink);
    letter-spacing: 0.08em;
}

.mes_reasoning_arrow {
    color: var(--g2);
}

.mes_reasoning {
    border: 0 !important;
    border-radius: 0 !important;
    padding: 4px 0 0 0 !important;
    margin: 0 !important;
    font-family: var(--fang);
    font-weight: 400 !important;
    font-size: 0.9em;
    line-height: 1.65 !important;
    color: var(--g1);
}

.mes_reasoning p {
    margin-bottom: 0.4em !important;
}

/* ---------- 输入区 = 稿件录入 ---------- */
#form_sheld {
    background: var(--paper);
    border-top: 2px solid var(--ink);
    padding-top: 4px;
}

#send_form {
    border: 0 !important;
    border-radius: 0 !important;
    background: var(--paper) !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}

#send_form:has(#send_textarea:focus-visible) {
    outline: none !important;
    border-color: transparent !important;
}

#send_textarea {
    font-family: var(--song) !important;
    font-size: var(--mainFontSize) !important;
    color: var(--ink) !important;
    text-shadow: none !important;
    --progColor: var(--red);
    --progFlashColor: var(--red);
    --progSuccessColor: var(--ink);
    --progErrorColor: var(--red);
}

#send_textarea::placeholder {
    color: var(--g2) !important;
    font-family: var(--song);
}

#leftSendForm > div,
#rightSendForm > div:not(.mes_stop) {
    color: var(--ink);
    opacity: 0.85;
}

#send_but {
    color: var(--red) !important;
    opacity: 1 !important;
}

#send_form .mes_stop {
    color: var(--red);
}

#options_button {
    color: var(--ink);
}

/* ===== drawers.css ===== */
/* =====================================================================
   drawers.css — 三联生活周刊主题 / 抽屉与二级面板
   scope: 左右抽屉容器、通用控件、用户设置、角色列表、角色编辑、
          世界书、背景、扩展、API 连接
   uses tokens defined on body: --song --hei --kai --fang --din
        --red --ink --g1 --g2 --rule --rule2 --band
   白底 / 无圆角 / 无阴影 / 无毛玻璃。选择器多数需要 !important 压过
   ST 源码里内联的 border-radius / backdrop-filter / 彩色底 等默认值。

   本文件覆盖区域（对应任务分工）：
   - 抽屉容器 / 顶栏图标下划线
   - 通用控件（range / text_pole / select / textarea / menu_button /
     inline-drawer / checkbox / flex-container 标签）
   - 用户设置抽屉
   - 角色列表（仅 #rm_print_characters_block 作用域内的 .ch_name）
   - 角色编辑面板
   - 世界书
   - 背景
   - 扩展
   - API 连接

   源码核对情况（ST 1.18，/public 下）：
   - 已确认存在并核对行号：见各分区注释。
   - 拿不准 / 源码里没找到、按最接近的真实选择器替代：
     · `.api-key-input` —— 源码中不存在这个类，API Key 输入框实际用的是
       `.text_pole`（如 #api_key_novel、#api_key_togetherai 等），本文件
       按 `#rm_api_block input.text_pole` 处理，不单独定义 .api-key-input。
     · `#ui-preset-block` —— 源码中不存在，实际 id 是 `#UI-presets-block`
       （index.html:4912），本文件两个都写了选择器以防万一，以
       `#UI-presets-block` 为准。
     · `.drawer-icon.openIcon` 在源码里只有 transition，没有默认视觉样式
       （closedIcon 才有 opacity:.3），hover/active 下划线是本文件新增，
       未在源码里找到冲突规则，风险较低。
     · world-info.css 里没有单独的“关键词/内容”选择器给 DIN 编号用，
       条目标题结构由 JS 动态生成（.WIEntryHeaderTitle 等未在允许名单
       内），因此编号仅通过 `.world_entry_form_control label h4` 一类
       通用标签实现视觉效果，没有强绑定具体序号来源，如显示错位需要
       改 JS 侧的类名，不在本次 CSS 范围内。
   ===================================================================== */


/* =====================================================================
   1. 抽屉容器 / 顶栏图标
   style.css:5479 .drawer-icon
   style.css:5486 .drawer-icon.openIcon
   style.css:5490 .drawer-icon.closedIcon
   style.css:5547 .drawer-content
   style.css:5605-5641 .fillLeft / .fillRight
   ===================================================================== */
.drawer-content{
  background:var(--paper) !important;
  color:var(--ink) !important;
  border-radius:0 !important;
  border:1px solid var(--rule) !important;
  box-shadow:none !important;
  backdrop-filter:none !important;
  -webkit-backdrop-filter:none !important;
  font-family:var(--song);
}
#left-nav-panel{border-right:0 !important;border-left:1px solid var(--rule) !important}
#right-nav-panel{border-left:0 !important;border-right:1px solid var(--rule) !important}
.fillLeft,
.fillRight{box-shadow:none !important}

/* 顶栏图标：本体不动，只加 hover/active 下的红色下划线 */
.drawer-icon{position:relative}
.drawer-icon.openIcon{color:var(--red) !important;opacity:1 !important}
.drawer-icon.openIcon::after{
  content:"";position:absolute;left:2px;right:2px;bottom:-2px;
  height:2px;background:var(--red);
}
.drawer-icon.closedIcon:hover{color:var(--ink);opacity:1 !important}
.drawer-icon.closedIcon:hover::after{
  content:"";position:absolute;left:2px;right:2px;bottom:-2px;
  height:2px;background:var(--ink);
}


/* =====================================================================
   2. 通用控件
   style.css:4168 .range-block / :4177 .range-block-title
   style.css:4217 .neo-range-input / :4230 .neo-range-slider
   style.css:2669 .text_pole / :2681 select.text_pole
   style.css:3039 select
   style.css:1544 textarea
   style.css:3818 .menu_button / :5441 .menu_button_icon
   style.css:5527 .inline-drawer-header / :5535 .inline-drawer-content
   style.css:4591 .checkbox_label
   style.css:4046 input[type=checkbox]
   ===================================================================== */

/* 滑块 */
.range-block{margin-bottom:8px}
.range-block-title{
  font-family:var(--hei);color:var(--ink);text-align:left;
  font-size:12.5px;margin-bottom:3px;
}
.neo-range-slider,
input[type=range]{
  background:var(--rule2) !important;
  box-shadow:none !important;
  border-radius:0 !important;
  filter:none !important;
  height:2px !important;
}
.neo-range-slider::-webkit-slider-thumb,
input[type=range]::-webkit-slider-thumb{
  -webkit-appearance:none;appearance:none;
  width:10px;height:10px;border-radius:50%;
  background:var(--red);border:0;cursor:pointer;
}
.neo-range-slider:hover,
input[type=range]:hover{filter:brightness(1) !important}
.neo-range-input{
  background:var(--paper) !important;border:1px solid var(--rule) !important;
  border-radius:0 !important;color:var(--ink);
  font-family:var(--din);text-align:center;
}
.range-block-counter{font-family:var(--din);color:var(--g1)}

/* 文本输入 / 下拉 / 文本域 */
.text_pole,
select,
.drawer-content textarea{
  background:var(--paper) !important;
  color:var(--ink) !important;
  border:1px solid var(--rule) !important;
  border-radius:0 !important;
  font-family:var(--song);
  box-shadow:none !important;
}
select{
  background-image:none !important;
  padding-right:18px;
}
.text_pole::placeholder,
.drawer-content textarea::placeholder{color:var(--g2) !important;opacity:1}
select option{background:var(--paper) !important;color:var(--ink) !important}
select option:not(:checked){background:var(--paper) !important;color:var(--g1) !important}

/* 按钮 */
.menu_button{
  background:var(--paper) !important;
  color:var(--ink) !important;
  border:1px solid var(--ink) !important;
  border-radius:0 !important;
  font-family:var(--hei);
}
.menu_button:not(.disabled):not([disabled]):hover,
.menu_button:not(.disabled):not([disabled]).active{
  background:var(--band) !important;
}
.menu_button.primary,
.menu_button.api_button,
#ui-preset-save-button,
#UI-presets-block .menu_button.primary{
  background:var(--red) !important;
  border-color:var(--red) !important;
  color:#fff !important;
}
.menu_button_icon span{font-family:var(--hei)}

/* 折叠块 */
.inline-drawer-header{
  font-family:var(--hei);color:var(--ink);
  border-bottom:1px solid var(--rule);padding-bottom:4px;
}
.inline-drawer-toggle:hover{color:var(--red)}
.inline-drawer-content{color:var(--ink)}

/* 复选框 */
input[type=checkbox]{
  border:1px solid var(--ink) !important;
  border-radius:0 !important;
  background:var(--paper) !important;
  box-shadow:none !important;
  filter:none !important;
}
input[type=checkbox]::before{box-shadow:inset 1em 1em var(--red) !important}
.checkbox_label{font-family:var(--song);color:var(--ink)}

/* flex-container 内标签文字统一用宋体，数字类用 DIN（token-counter 等） */
.flex-container label,
.flex-container h4,
.flex-container h5{font-family:var(--song);color:var(--ink)}
.flex-container [data-token-counter]{font-family:var(--din);color:var(--g1)}


/* =====================================================================
   3. 用户设置抽屉
   index.html:4869 #user-settings-block
   index.html:4910 #user-settings-block-content
   index.html:4912 #UI-presets-block（任务书里写的 #ui-preset-block 在源码
                     中不存在，未找到该 id）
   index.html:4929 #themes
   index.html:5313 #customCSS
   ===================================================================== */
#user-settings-block,
#user-settings-block-content{background:var(--paper);color:var(--ink)}
#UI-presets-block,
#ui-preset-block{border-bottom:1px solid var(--rule);padding-bottom:8px;margin-bottom:8px}
#themes{font-family:var(--hei)}
#customCSS{
  font-family:"SF Mono",Menlo,monospace !important;
  background:var(--band) !important;
  border:1px solid var(--rule) !important;
  color:var(--ink) !important;
}


/* =====================================================================
   4. 角色列表（目录页）——仅作用于 #rm_print_characters_block 内
   style.css:3164 #rm_characters_block
   style.css:2905 #rm_print_characters_block
   style.css:3276 .bogus_folder_select, .character_select
   style.css:3296 .ch_name（全局，作用域收窄到列表内）
   style.css:3300 .character_name_block
   style.css:3329 .ch_description
   style.css:3324 .character_select .avatar
   style.css:3218 #character_search_bar
   css/tags.css:46 .tag / :106 .tags / :144 .tag_name
   ===================================================================== */
#rm_characters_block,
#rm_print_characters_block{background:var(--paper);color:var(--ink)}
#rm_print_characters_block .character_select,
#rm_print_characters_block .bogus_folder_select{
  border-radius:0 !important;
  border-bottom:1px solid var(--rule2);
  background:transparent !important;
}
