/* =====================================================================
   一、弹窗 dialog.popup（新版）
   来源：public/css/popup.css:9-221；public/index.html 里各处 <dialog class="popup">
   效果图：preview.html 的 dialog.popup 规则（白底、顶部 4px 红条、轻投影、无圆角）
   ===================================================================== */
body dialog.popup {
    background-color: var(--paper) !important;
    color: var(--ink) !important;
    font-family: var(--song) !important;
    font-size: 13.5px !important;
    border: 0 !important;
    border-top: 4px solid var(--red) !important;
    border-radius: 0 !important;
    box-shadow: 0 4px 18px rgba(0, 0, 0, .18) !important;
}

/* 弹窗打开时的毛玻璃遮罩关掉，保持无毛玻璃基调（popup.css:101-116） */
body .popup[open]::backdrop {
    background-color: rgba(34, 35, 34, .35) !important;
    -webkit-backdrop-filter: none !important;
    backdrop-filter: none !important;
}

/* popup.css:49-61 .popup-body */
body .popup .popup-body {
    padding: 14px 18px;
}

/* popup.css:62-73 .popup-content：标题黑体，正文宋体 */
body .popup .popup-content {
    font-family: var(--song);
    color: var(--ink);
    text-align: left;
}

body .popup .popup-content h2,
body .popup .popup-content h3,
body .popup .popup-content h4 {
    font-family: var(--hei);
    font-weight: 700;
    color: var(--ink);
    border-bottom: 1px solid var(--ink);
    padding-bottom: 6px;
    margin-bottom: 10px;
}

/* popup.css:161-173 .popup-inputs / .popup-input */
body .popup .popup-inputs {
    font-family: var(--fang);
    color: var(--g1);
}

body .popup .popup-input,
body .popup textarea.popup-input,
body .popup input.popup-input {
    font-family: var(--song);
    background: var(--paper);
    border: 1px solid var(--rule);
    border-radius: 0;
    color: var(--ink);
}

body .popup .popup-input:focus-visible {
    border-color: var(--red);
    outline: 1px solid var(--red);
}

/* popup-crop-wrap：裁剪图，只加灰线，不加圆角/阴影 */
body .popup .popup-crop-wrap {
    border: 1px solid var(--rule);
}

/* popup.css:175-207 .popup-controls / 按钮：确定红底白字，取消白底墨线方角 */
body .popup .popup-controls {
    gap: 12px;
}

body .popup .popup-controls .menu_button {
    border-radius: 0;
    font-family: var(--hei);
    background: var(--paper);
    border: 1px solid var(--ink);
    color: var(--ink);
    box-shadow: none;
}

body .popup .popup-controls .menu_button.popup-button-ok,
body .menu_button.popup-button-ok {
    background-color: var(--red) !important;
    border-color: var(--red) !important;
    color: #fff !important;
}

body .popup .popup-controls .menu_button.popup-button-ok:hover,
body .menu_button.popup-button-ok:hover {
    background-color: var(--ink) !important;
    border-color: var(--ink) !important;
}

body .popup .popup-controls .menu_button.popup-button-cancel:hover,
body .popup .popup-controls .menu_button:not(.popup-button-ok):hover {
    color: var(--red);
    border-color: var(--red);
}

/* popup.css:208-220 .popup-button-close（右上角 × ） */
body .popup .popup-button-close {
    color: var(--ink);
    filter: none;
}

body .popup .popup-button-close:hover {
    color: var(--red);
}

/* popup.css:87-122 打开/关闭动画：只调时长内的视觉，不改动画机制本身 */
body .popup[opening],
body .popup[closing] {
    box-shadow: 0 4px 18px rgba(0, 0, 0, .18);
}


